import { clamp } from './playroom.js';
export const guitarToneKey='hitori-room:guitar-tone:v1';
export const effectNames={drive:'失真',delay:'延迟',reverb:'混响'};
export const defaultTone={version:1,name:'放学后的清音',order:['drive','delay','reverb'],enabled:{drive:false,delay:true,reverb:true},drive:.3,delayTime:.24,feedback:.28,delayMix:.2,reverbMix:.25};
export const tonePresets=[defaultTone,{...defaultTone,name:'舞台上的第一束光',enabled:{drive:true,delay:true,reverb:true},drive:.55,delayTime:.18,delayMix:.14,reverbMix:.15},{...defaultTone,name:'雨夜里的一根弦',order:['drive','reverb','delay'],enabled:{drive:false,delay:true,reverb:true},delayTime:.43,feedback:.5,delayMix:.4,reverbMix:.5}];
export function validateTone(v){if(!v||v.version!==1)throw new Error('音色格式无法读取。');const order=Array.isArray(v.order)&&v.order.length===3&&new Set(v.order).size===3&&v.order.every(id=>Object.hasOwn(effectNames,id))?[...v.order]:[...defaultTone.order];return {version:1,name:String(v.name||'我的音色').slice(0,32),order,enabled:Object.fromEntries(Object.keys(effectNames).map(id=>[id,v.enabled?.[id]===true])),drive:clamp(v.drive,0,1),delayTime:clamp(v.delayTime,.08,.65),feedback:clamp(v.feedback,0,.65),delayMix:clamp(v.delayMix,0,.65),reverbMix:clamp(v.reverbMix,0,.75)};}
export function moveEffect(input,id,offset){const tone=validateTone(input),index=tone.order.indexOf(id),next=index+offset;if(index<0||next<0||next>=tone.order.length)return tone;[tone.order[index],tone.order[next]]=[tone.order[next],tone.order[index]];return tone;}
export function parseToneFile(text){try{if(new TextEncoder().encode(text).length>16384)throw new Error();const value=JSON.parse(text);if(typeof value.name!=='string'||!Array.isArray(value.order)||value.order.length!==3||new Set(value.order).size!==3||!value.order.every(id=>Object.hasOwn(effectNames,id))||!['drive','delayTime','feedback','delayMix','reverbMix'].every(key=>Number.isFinite(value[key])))throw new Error();return validateTone(value);}catch{throw new Error('请选择有效的音色 JSON，文件不能超过 16 KiB。');}}
